head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > resetButtonDisplay]<br/>SearchBox 컴포넌트의 Reset 버튼 표시 방식을 설정합니다.",
    "validation" : [        
        "'hide' 로 설정하면 Reset 버튼을 생성하지 않아야 합니다.",
        "'show' (기본값) 로 설정하면 포커스 여부와 관계없이 값이 있을 때 Reset 버튼을 표시해야 합니다.",
        "'toggle' 로 설정하면 포커스가 들어오고 값이 있을 때 Reset 버튼을 표시하며, 포커스가 빠지면 숨겨야 합니다.",
        "속성값을 설정하지 않으면 config.xml 의 WebSquare/searchbox/resetButtonDisplay/@value 값이 적용되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        resetButtonDisplay : con_resetButtonDisplay.getText(),
    }

    let cList = $c.gcm.createCList(properties);

    await $c.gcm.createBasicSearchBox(cList);

    // searchbox 내부 input 에 native focus/blur 리스너 등록
    // (searchbox 엔진은 ev:onfocus 를 fireEvent 하지 않으므로 native 리스너로 우회)
    // 이벤트 직후 display 갱신 타이밍을 위해 setTimeout 으로 wait 후 상태 출력
    if (target1.input && target1.input.render) {
        target1.input.render.addEventListener('focus', function () {
            setTimeout(function () {
                scwin.printResetBtnState("[onfocus]");
            }, 100);
        });
        target1.input.render.addEventListener('blur', function () {
            setTimeout(function () {
                scwin.printResetBtnState("[onblur]");
            }, 100);
        });
    }
}



// Reset 버튼 상태 출력 (label + 입력값 + DOM 존재 여부 + display)
scwin.printResetBtnState = function (label) {
    let resetBtn = document.querySelector("[id*='target1___reset']");
    let inputValue = target1.getValue();

    if (resetBtn) {
        let display = resetBtn.style.display;
        let visible = (display !== 'none') ? 'visible' : 'hidden';
        wf_body_bottom.getObj("scwin").setReturnValue(label + " value='" + inputValue + "' Reset DOM=O display='" + display + "' (" + visible + ")");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue(label + " value='" + inputValue + "' Reset DOM=X");
    }
};



// SearchBox 입력값 설정 (자동으로 Reset 버튼 상태 출력)
scwin.btn_setValue_onclick = function (e) {
    target1.setValue("검색어");    
};



// SearchBox 입력값 초기화 (자동으로 Reset 버튼 상태 출력)
scwin.btn_clearValue_onclick = function (e) {
    target1.setValue("");
    scwin.printResetBtnState("[setValue('')]");
};
